head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//

/**
 * @method
 * @name CheckReqInfo
 * @description desc
 * @param {string} fm desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.CheckReqInfo = function(fm) {
    if (GetByte(fm.bnd_apct_tp_cd.getValue()) == 0) {
        alert("신청인 구분을 입력하십시오.");
        fm.bnd_apct_tp_cd.focus();
        return false;
    }
    if (GetByte(fm.apct_nm.getValue()) == 0) {
        alert("이름을 입력하십시오.");
        fm.apct_nm.focus();
        return false;
    }

    //전화번호의 지역번호필드는 입력하지 않을경우 '00'으로 자동저장
    //if ( GetByte(fm.apct_tel_no1.value)==0 || GetByte(fm.apct_tel_no2.value)==0 || GetByte(fm.apct_tel_no3.value)==0 ) {
    if (GetByte(fm.apct_tel_no2.getValue()) == 0 || GetByte(fm.apct_tel_no3.getValue()) == 0) {
        alert("전화번호를 입력하십시오.");
        fm.apct_tel_no1.focus();
        return false;
    }
    if (GetByte(fm.apct_fax_no1.getValue()) == 0 || GetByte(fm.apct_fax_no2.getValue()) == 0 || GetByte(fm.apct_fax_no3.getValue()) == 0) {
        alert("팩스번호를 입력하십시오.");
        fm.apct_fax_no1.focus();
        return false;
    }
    if (GetByte(fm.encryp_apct_email1.getValue()) == 0) {
        alert("이메일을 입력하십시오.");
        fm.encryp_apct_email1.focus();
        return false;
    } else if (GetByte(fm.encryp_apct_email2.getValue()) == 0) {
        alert("이메일을 입력하십시오.");
        fm.encryp_apct_email2.focus();
        return false;
    } else {
        if (!CheckEmail(fm.encryp_apct_email1.getValue() + '@' + fm.encryp_apct_email2.getValue())) {
            alert("이메일이 올바르지 않습니다.");
            fm.encryp_apct_email2.focus();
            return false;
        }
    }

    //개인정보수집동의 체크
    if (fm.prn_info_collct_consnt_yn.checked == false) {
        alert("개인정보 수집 및 이용에 동의해 주세요.");
        fm.prn_info_collct_consnt_yn.focus();
        return false;
    }
    return true;
};


//휴대전화번호 입력체크
/**
 * @method
 * @name CheckReqInfo_Cellphone
 * @description desc
 * @param {string} fm desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.CheckReqInfo_Cellphone = function(fm) {
    if (GetByte(fm.encryp_cellphone_no1.getValue()) == 0 || GetByte(fm.encryp_cellphone_no2.getValue()) == 0 || GetByte(fm.encryp_cellphone_no3.getValue()) == 0) {
        alert("휴대전화번호를 입력하십시오.");
        fm.encryp_cellphone_no1.focus();
        return false;
    }
    return true;
};
